"""Reproducible import of the downloaded NASA CSV; never fixes suspect readings."""
import csv,json,re,hashlib,pathlib,collections,datetime
root=pathlib.Path(__file__).resolve().parents[1]
path=root/'data/bass2-source.csv'
sha=hashlib.sha256(path.read_bytes()).hexdigest()
with path.open(encoding='utf-8-sig',newline='') as f:
    reader=csv.DictReader(f); raw_rows=list(reader)
def number(value):
    s=str(value or '').strip()
    return float(s) if re.fullmatch(r'-?\d+(?:\.\d+)?',s) else None
records=[]
for index,raw in enumerate(raw_rows,2):
    raw={k.strip():v for k,v in raw.items()}
    text=raw['Fuel Sample Material'];lower=text.lower(); flags=['Independent sensor interpretation not verified']
    material='PMMA' if 'pmma' in lower else 'SIBAL fabric' if 'sibal' in lower else 'Nomex' if 'nomex' in lower else 'Wax' if 'wax' in lower else 'Unspecified film' if 'film' in lower or 'micron' in lower else 'Unspecified solid'
    if material.startswith('Unspecified'):flags.append('Material identity incomplete')
    thickness=None
    micron_values=re.findall(r'(\d+(?:\.\d+)?)\s*micron',lower)
    mm_values=re.findall(r'(\d+(?:\.\d+)?)\s*mm\b',lower)
    if len(micron_values)==1:thickness=float(micron_values[0])/1000
    elif len(mm_values)==1:thickness=float(mm_values[0])
    elif len(micron_values)+len(mm_values)>1:flags.append('Multiple thickness values; no scalar normalization')
    width=re.search(r'(\d+(?:\.\d+)?)\s*cm\s*wide',lower)
    oi=number(raw['Calibrated  initial O2 % by vol']);of=number(raw['Calibrated final O2 % by vol'])
    ci=number(raw['Initial CO (ppm)']);cf=number(raw['Final CO (ppm)'])
    if of is not None and oi is not None and abs(of-oi)>5:flags.append('Unusual oxygen change; preserve raw value')
    if any(v is not None and v<0 for v in [ci,cf]):flags.append('Negative CO sensor reading; preserve raw value')
    if number(raw['Air display']) is None:flags.append('Air display contains changing or nonnumeric settings')
    for key in ['Calibrated  initial O2 % by vol','Calibrated final O2 % by vol','Initial CO2 % by vol','Final CO2 % by vol','Initial CO (ppm)','Final CO (ppm)']:
        value=raw[key]
        if number(value) is None:flags.append(f'{key}: missing or non-scalar value {value!r}; numeric value left null')
    try:
        day=datetime.datetime.strptime(raw['Date'],'%m/%d/%Y')
        if day.timetuple().tm_yday!=int(raw['GMT']):flags.append('Date and GMT day-of-year disagree; source preserved')
        if day.year not in [2014,2016]:flags.append('Date year differs from dominant 2014/2016 records; source preserved')
    except ValueError:flags.append('Date could not be validated; source preserved')
    if not raw['Air display'].strip():flags.append('Air display missing')
    if re.search(r'cm\s*/\s*s',raw['Air display'],re.I):flags.append('Air display includes an explicit velocity annotation plus settings; no scalar conversion')
    records.append(dict(id=raw['Test #'],investigation='bass2',material=material,raw_material=text,thickness_mm=thickness,width_cm=float(width[1]) if width else None,length_cm=None,airflow_cms=None,air_display=raw['Air display'],oxygen_initial_pct=oi,oxygen_final_pct=of,co_initial_ppm=ci,co_final_ppm=cf,co2_initial_pct=number(raw['Initial CO2 % by vol']),co2_final_pct=number(raw['Final CO2 % by vol']),pressure_kpa=None,gravity='Microgravity',outcome='Not reported in CSV',source='bass2',location=f'PSI-25_Experimental table_BASS-II.csv, CSV row {index}',verification='Source transcribed',flags=flags,notes='Transcription cross-checked against live PSI-25 table. O2 headers say calibrated; independent sensor interpretation and scalar airflow conversion are not verified.',source_sha256=sha,raw=raw))
ids=[r['id'] for r in records]
assert len(ids)==len(set(ids)), 'Duplicate test identifiers require investigation'
(root/'data/bass2-generated.mjs').write_text('// Generated by scripts/ingest_bass2.py; retain raw source.\nexport const bass2Records = '+json.dumps(records,ensure_ascii=False,indent=2)+';\n')
(root/'data/ingestion-audit.json').write_text(json.dumps(dict(source=str(path.name),sha256=sha,record_count=len(records),repository_display_count=130,discrepancy='Resolved: 129 nonempty records plus one blank trailing row in the NASA web table',repository_blank_rows=1,discrepancy_resolved=True,source_field_comparison='data/source-verification.json',date='2026-11-15',pi_counts=dict(collections.Counter(r['PI'] for r in raw_rows))),indent=2))
print(f'Imported {len(records)} source-transcribed rows; sensor interpretation pending; SHA256 {sha}')
